<?php

declare(strict_types=1);

namespace App\Domain\OnlinePayment\Gateway;

use Carbon\CarbonInterface;

/**
 * One payment to start at the provider — what the gateway sends, in our words.
 */
final readonly class PaymentRequest
{
    public function __construct(
        /** What the provider charges — the gross, two places. */
        public string $amount,
        /** Ours, generated by the server, unique — the webhook is matched by it. */
        public string $orderReference,
        public string $internalReference,
        public string $firstName,
        public string $lastName,
        public string $phone,
        public ?string $cardNumber = null,
        public ?string $serviceMobileNumber = null,
        public ?string $birthYear = null,
        public ?string $qrContent = null,
        public ?string $redirectUrl = null,
        /** When a card link stops taking payments — the attempt's own end. */
        public ?CarbonInterface $expiresAt = null,
    ) {}
}
